WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_rd_dr_combo'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '组合整除判定', 'kp-rd-dr-combo', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "组合整除（7、11、13）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "遇到大质数的整除判定。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、被 11 整除的秘诀"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "奇数位上的数字之和，与偶数位上的数字之和，两者的差是 11 的倍数（含 0）。"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "例如：13574。奇数位和 = 1+5+4 = 10。偶数位和 = 3+7 = 10。10 - 10 = 0。所以 13574 能被 11 整除！"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、7、11、13 通用法则"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "把数字从右往左，每三位截成一段。奇数段之和减去偶数段之和，差值如果能被 7/11/13 整除，原数就能被整除。"}]}]}$$ AS jsonb), NULL, '组合整除判定的核心考点与实战推导。', category_node.id, CAST('["数量关系", "组合整除判定"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_rd_dr_combo", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
